<script setup lang="ts">
import type { Audit } from '~/types/billing'
import { billingDate } from '~/utils/billing'
definePageMeta({layout:'admin',middleware:'superadmin'})
const {rows,pagination,pending,error,refresh,page}=await useManagement<Audit>('audit')
</script>
<template><div><p class="eyebrow">Accountability</p><h1 class="page-title mt-2">Audit log</h1><p class="mt-2 text-text-secondary">A read-only history of administrative changes and Stripe synchronization.</p><div class="surface mt-8 overflow-hidden"><LoadingState v-if="pending"/><p v-else-if="error" class="p-8" role="alert">Unable to load activity. <button class="text-brand" @click="refresh()">Retry</button></p><div v-else class="overflow-x-auto"><table class="admin-table"><thead><tr><th>Event</th><th>Actor</th><th>Subject</th><th>Date</th><th>Details</th></tr></thead><tbody><tr v-for="entry in rows" :key="entry.id"><td class="font-medium">{{ entry.action }}</td><td>{{ entry.actor?.email || 'System / console' }}</td><td>{{ entry.subject_type }} #{{ entry.subject_id }}</td><td>{{ billingDate(entry.created_at) }}</td><td><details><summary class="cursor-pointer text-brand">View changes</summary><pre class="mt-3 max-h-64 max-w-md overflow-auto whitespace-pre-wrap rounded bg-surface2 p-3 text-xs">{{ JSON.stringify(entry.changes,null,2) }}</pre></details></td></tr><tr v-if="!rows.length"><td colspan="5" class="py-12 text-center">No administrative events yet.</td></tr></tbody></table></div><AdminPagination v-if="pagination" :current="pagination.current_page" :last="pagination.last_page" :total="pagination.total" :pending="pending" @change="page=$event"/></div></div></template>
